1	package checkpoint
2	
3	import (
4		"context"
5		"fmt"
6	
7		"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
8	)
9	
10	// CheckpointReader provides read access to checkpoint-level persistent data.
11	//
12	//nolint:revive // CheckpointReader stutter is accepted — the name marks the checkpoint (vs session) read tier.
13	type CheckpointReader interface {
14		Read(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error)
15		List(ctx context.Context) ([]CheckpointInfo, error)
16	}
17	
18	// SessionReader provides read access to session-level data within a checkpoint.
19	type SessionReader interface {
20		ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error)
21		ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, error)
22		ReadSessionPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error)
23		ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, string, error)
24	}
25	
26	// PersistentStore provides the production persistent checkpoint storage surface:
27	// checkpoint-level reads, session-level reads, and the unified Write. Writes go
28	// through Writer.Write(ctx, WriteRequest); the concrete per-operation methods
29	// live on the git implementation as the methods Write dispatches to.
30	type PersistentStore interface {
31		CheckpointReader
32		SessionReader
33		Writer
34	}
35	
36	// WriteRequest is a single persistent-store write command. The set is closed to
37	// other packages: only types in this package can implement it, sealed via the
38	// unexported isWriteRequest marker. A store dispatches on the concrete type; a
39	// mirror/fan-out store forwards the same value to each backend's Write.
40	//
41	// Three requests are session-level (Session, SessionTranscript, SessionSummary)
42	// and one is checkpoint-level (CheckpointAttribution). Adding a write operation
43	// is a new request type plus one dispatch case — the Store interface stays
44	// unchanged and existing backends keep compiling.
45	type WriteRequest interface {
46		isWriteRequest()
47	}
48	
49	// Session creates or replaces a session document within a checkpoint,
50	// materializing the checkpoint on its first session. (session-level)
51	type Session WriteOptions
52	
53	// SessionTranscript replaces a session's transcript, prompts, and skill events
54	// at stop time without clobbering sibling fields. (session-level)
55	type SessionTranscript UpdateOptions
56	
57	// SessionSummary rewrites only the summary of the checkpoint's latest session.
58	// (session-level)
59	type SessionSummary struct {
60		CheckpointID id.CheckpointID
61		Summary      *Summary
62	}
63	
64	// CheckpointAttribution rewrites the checkpoint root's combined attribution
65	// across all sessions. (checkpoint-level)
66	//
67	//nolint:revive // CheckpointAttribution stutter is accepted — the name makes the checkpoint (vs session) tier explicit.
68	type CheckpointAttribution struct {
69		CheckpointID id.CheckpointID
70		Attribution  *Attribution
71	}
72	
73	func (Session) isWriteRequest()               {}
74	func (SessionTranscript) isWriteRequest()     {}
75	func (SessionSummary) isWriteRequest()        {}
76	func (CheckpointAttribution) isWriteRequest() {}
77	
78	// Writer is the persistent-store write surface: a single Write that accepts any
79	// WriteRequest. It is the natural type for mirror fan-out.
80	type Writer interface {
81		Write(ctx context.Context, req WriteRequest) error
82	}
83	
84	// ReadCheckpoint reads a checkpoint summary and normalizes a nil store response
85	// into ErrCheckpointNotFound.
86	func ReadCheckpoint(ctx context.Context, reader CheckpointReader, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
87		if err := ctx.Err(); err != nil {
88			return nil, err //nolint:wrapcheck // Propagating context cancellation
89		}
90	
91		summary, err := reader.Read(ctx, checkpointID)
92		if err != nil {
93			return nil, fmt.Errorf("read persistent checkpoint: %w", err)
94		}
95		if summary == nil {
96			return nil, ErrCheckpointNotFound
97		}
98		return summary, nil
99	}
100	
101	// ReadLatestSessionContent reads the latest session from an already-resolved
102	// session reader and summary.
103	func ReadLatestSessionContent(ctx context.Context, reader SessionReader, checkpointID id.CheckpointID, summary *CheckpointSummary) (*SessionContent, error) {
104		if summary == nil || len(summary.Sessions) == 0 {
105			return nil, ErrCheckpointNotFound
106		}
107		latestIndex := len(summary.Sessions) - 1
108		content, err := reader.ReadSessionContent(ctx, checkpointID, latestIndex)
109		if err != nil {
110			return nil, fmt.Errorf("read session %d content: %w", latestIndex, err)
111		}
112		return content, nil
113	}
114	
115	// ReadRawSessionLogForCheckpoint reads a checkpoint's latest-session transcript;
116	// it needs both reader tiers (resolve the checkpoint, then its latest session).
117	func ReadRawSessionLogForCheckpoint(ctx context.Context, reader interface {
118		CheckpointReader
119		SessionReader
120	}, checkpointID id.CheckpointID) ([]byte, string, error) {
121		if err := ctx.Err(); err != nil {
122			return nil, "", err //nolint:wrapcheck // Propagating context cancellation
123		}
124	
125		summary, err := ReadCheckpoint(ctx, reader, checkpointID)
126		if err != nil {
127			return nil, "", err
128		}
129	
130		content, err := ReadLatestSessionContent(ctx, reader, checkpointID, summary)
131		if err != nil {
132			return nil, "", err
133		}
134		return content.Transcript, content.Metadata.SessionID, nil
135	}
