74	func newTokensProfileCmd() *cobra.Command {
75		var jsonFlag bool
76		var limitFlag int
77		var allFlag bool
78	
79		cmd := &cobra.Command{
80			Use:   "profile",
81			Short: "Aggregate token usage and recommendations across checkpoint history",
82			Long: `Aggregate token usage and recommendations across committed checkpoint history.
83	
84	The profile reads committed checkpoint metadata only. It does not inspect
85	transcripts or source files, so it is deterministic and avoids adding token
86	cost while diagnosing token usage. By default it scans the latest 50 committed
87	checkpoints; use --limit or --all to change the scope.`,
88			Args: cobra.NoArgs,
89			RunE: func(cmd *cobra.Command, _ []string) error {
90				limit := limitFlag
91				if allFlag {
92					limit = 0
93				} else if limit <= 0 {
94					return errors.New("--limit must be positive unless --all is used")
95				}
96				return runTokensProfile(cmd.Context(), cmd, jsonFlag, limit)
97			},
98		}
99	
100		cmd.Flags().BoolVar(&jsonFlag, "json", false, "Output as JSON")
101		cmd.Flags().IntVar(&limitFlag, "limit", 50, "Maximum committed checkpoints to analyze")
102		cmd.Flags().BoolVar(&allFlag, "all", false, "Analyze all committed checkpoints")
103		cmd.MarkFlagsMutuallyExclusive("limit", "all")
