107	func runTokensProfile(ctx context.Context, cmd *cobra.Command, jsonOutput bool, limit int) error {
108		repo, err := openRepository(ctx)
109		if err != nil {
110			cmd.SilenceUsage = true
111			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository.")
112			return NewSilentError(err)
113		}
114		defer repo.Close()
115	
116		store := checkpoint.NewGitStore(repo, checkpoint.ResolveRefs(ctx))
117		store.SetBlobFetcher(FetchBlobsByHash)
118		infos, err := store.List(ctx)
119		if err != nil {
120			return fmt.Errorf("failed to list checkpoints: %w", err)
121		}
122	
123		report, err := buildTokensProfileReport(ctx, store, infos, limit)
124		if err != nil {
125			return err
126		}
127	
128		if jsonOutput {
129			return writeTokensProfileJSON(cmd.OutOrStdout(), report)
130		}
131		writeTokensProfileText(cmd.OutOrStdout(), report)
132		return nil
