188	func limitTokensProfileCheckpoints(infos []checkpoint.CheckpointInfo, limit int) []checkpoint.CheckpointInfo {
189		if limit <= 0 || len(infos) <= limit {
190			return infos
191		}
192		return infos[:limit]
193	}
