func TestFanout_NoMirrorsReturnsPrimaryUnwrapped(t *testing.T) {
	t.Parallel()

	primary := &fakePrimaryWithAuthor{fakePrimary: &fakePrimary{}, author: Author{Name: "A"}}
	store := newFanoutStore(primary, nil)

