	t.Chdir(dir)
	writeRawSettings(t, dir, `{"enabled": true, "checkpoints": {"primary": {"type": "git"}, "mirrors": [{"type": "git"}]}}`)

	_, err := Open(context.Background(), repo, OpenOptions{})
